# M27 kernel transliteration check.## Verifies bit-exactness (or bit-closeness within one bf16 ulp on the ZF# divide) between:#   (a) the sandbox host reference `ofdm_loopback_reference` in#       tests/m27_ofdm/test_ofdm_m27.py#   (b) an independent second numpy transliteration written INLINE in this#       file so a bug in the primary reference cannot silently pass the#       silicon gate (a).## Runs on >= 2 seeds to guard against seed-specific luck.## References:#   - docs/M27_DESIGN.md sec 4 and sec 5 (kernel body order and open-loop#     rationale).#   - tools/m26_kernel_transliteration_check.py -- prior-art pattern.import sysfrom pathlib import Pathimport numpy as npfrom ml_dtypes import bfloat16_ROOT = Path(__file__).resolve().parents[1]sys.path.insert(0, str(_ROOT / "tests" / "m17_radix2_fft"))sys.path.insert(0, str(_ROOT / "tests" / "m27_ofdm"))# ------------------------------------------------------------------# Independent second reference (does NOT import test_ofdm_m27's function).N_FFT = 64N_CP = 16N_OSYM = N_FFT + N_CPN_SYM = 8N_DATA = 48N_PILOT = 4N_TAPS = 4N_DATA_TOTAL = N_DATA * N_SYMdef _data_kc():    kc = []    for k in range(1, 27):        if k in (7, 21):            continue        kc.append(k)    for k in range(-26, 0):        if k in (-7, -21):            continue        kc.append(k)    return np.array(kc, dtype=np.int32)DATA_KC = _data_kc()DATA_BINS = np.where(DATA_KC >= 0, DATA_KC, DATA_KC + N_FFT).astype(np.int32)PILOT_KC = np.array([+7, +21, -21, -7], dtype=np.int32)PILOT_BINS = np.where(PILOT_KC >= 0, PILOT_KC, PILOT_KC + N_FFT).astype(np.int32)PILOT_POL = np.array([+1.0, -1.0, +1.0, +1.0], dtype=np.float32)INV_N_FFT = np.float32(1.0 / N_FFT)def _pilot_bracket_v2(kc):    """Independent second implementation. Sorts pilots by centered k and    finds the closed-interval bracketing pair; edges use nearest-two    extrapolation (matches kernel/pilot_bracket)."""    order = np.argsort(PILOT_KC)    sk = PILOT_KC[order]    if kc <= int(sk[0]):        return int(order[0]), int(order[1])    if kc >= int(sk[-1]):        return int(order[-2]), int(order[-1])    for i in range(len(sk) - 1):        if int(sk[i]) <= kc <= int(sk[i + 1]):            return int(order[i]), int(order[i + 1])    raise RuntimeError("bracket search failed")def _second_reference(in_data_bf16, in_channel_bf16):    """Fully independent second reference. Vectorized numpy path."""    in_data = in_data_bf16.astype(np.float32)    in_chan = in_channel_bf16.astype(np.float32)    h_c = (in_chan[0::2] + 1j * in_chan[1::2]).astype(np.complex64)    out = np.zeros(2 * N_DATA_TOTAL, dtype=np.float32)    for sym in range(N_SYM):        # (1) Assemble X[k]        X = np.zeros(N_FFT, dtype=np.complex64)        for d in range(N_DATA):            base = 2 * (sym * N_DATA + d)            X[int(DATA_BINS[d])] = complex(in_data[base], in_data[base + 1])        for p in range(N_PILOT):            X[int(PILOT_BINS[p])] = complex(float(PILOT_POL[p]), 0.0)        # (2) IFFT via conj-trick        fftout = np.fft.fft(np.conj(X))        x = np.conj(fftout) * INV_N_FFT        # (3) CP-add (last N_CP samples prepended)        s = np.concatenate([x[N_FFT - N_CP:], x])        # (4) Channel FIR (np.convolve, take first s_len samples)        y_full = np.convolve(s, h_c, mode="full")[:N_OSYM]        # (5) CP-strip        y_n = y_full[N_CP:]        # (6) Forward FFT        Y = np.fft.fft(y_n)        # (7) Pilot LS        Hp = np.array([Y[int(PILOT_BINS[p])] * float(PILOT_POL[p])                       for p in range(N_PILOT)], dtype=np.complex64)        # (8) + (9) Linear interp + ZF        for d in range(N_DATA):            kc = int(DATA_KC[d])            pa, pb = _pilot_bracket_v2(kc)            span = float(PILOT_KC[pb] - PILOT_KC[pa])            t = (float(kc) - float(PILOT_KC[pa])) / span            Hd = Hp[pa] + t * (Hp[pb] - Hp[pa])            mag2 = float(Hd.real ** 2 + Hd.imag ** 2)            inv = 1.0 / mag2 if mag2 > 1e-12 else 0.0            Y_k = Y[int(DATA_BINS[d])]            x_re = (Y_k.real * Hd.real + Y_k.imag * Hd.imag) * inv            x_im = (-Y_k.real * Hd.imag + Y_k.imag * Hd.real) * inv            base_out = 2 * (sym * N_DATA + d)            out[base_out] = np.float32(x_re)            out[base_out + 1] = np.float32(x_im)    return out.astype(bfloat16)# ------------------------------------------------------------------# Cross-check driver.def _stub_aie_and_import_test():    import types    aie = types.ModuleType("aie")    aie_iron = types.ModuleType("aie.iron")    aie_iron.jit = (lambda fn: fn)    class _CompileTimeStub:        """Subscriptable stub so `CompileTime[int]` and `CompileTime[str]`        expressions at module scope do not raise TypeError."""        def __class_getitem__(cls, item):            return item        def __getitem__(self, item):            return item    aie_iron.CompileTime = _CompileTimeStub    for n in ("In", "Out", "ExternalFunction", "ObjectFifo",              "Program", "Runtime", "Worker"):        setattr(aie_iron, n, (lambda *a, **k: None))    aie_iron.get_current_device = (lambda: "stub")    aie.iron = aie_iron    sys.modules["aie"] = aie    sys.modules["aie.iron"] = aie_iron    aie_utils = types.ModuleType("aie.utils")    aie_utils_cfg = types.ModuleType("aie.utils.config")    aie_utils_cfg.cxx_header_path = (lambda: "/tmp")    aie_utils_host = types.ModuleType("aie.utils.hostruntime")    aie_utils_xrt = types.ModuleType("aie.utils.hostruntime.xrtruntime")    aie_utils_tensor = types.ModuleType("aie.utils.hostruntime.xrtruntime.tensor")    aie_utils_tensor.XRTTensor = None    for name, mod in [        ("aie.utils", aie_utils),        ("aie.utils.config", aie_utils_cfg),        ("aie.utils.hostruntime", aie_utils_host),        ("aie.utils.hostruntime.xrtruntime", aie_utils_xrt),        ("aie.utils.hostruntime.xrtruntime.tensor", aie_utils_tensor),    ]:        sys.modules[name] = mod    import test_ofdm_m27    return test_ofdm_m27def main():    m27 = _stub_aie_and_import_test()    seeds = [827, 828, 829]    channels = [        ("mild",       np.array([1.0, 0.15, 0.05, 0.02], dtype=np.complex64)),        ("delay-spread", np.array([1.0, 0.4, 0.2, 0.1], dtype=np.complex64)),        ("identity",   np.array([1.0, 0.0, 0.0, 0.0], dtype=np.complex64)),    ]    print("=== M27 kernel transliteration cross-check ===")    print(f"Seeds: {seeds}")    print(f"Channels: {[c[0] for c in channels]}")    n_pass = 0    n_fail = 0    for seed in seeds:        for name, taps in channels:            in_data, _syms = m27._random_qam16_burst(seed)            in_chan = m27._pack_channel(taps)            ref1 = m27.ofdm_loopback_reference(in_data, in_chan)            ref2 = _second_reference(in_data, in_chan)            ref1_f = ref1.astype(np.float32)            ref2_f = ref2.astype(np.float32)            diff = np.abs(ref1_f - ref2_f)            n_slots_diff = int(np.sum(diff > 0.0))            max_err = float(np.max(diff))            status = "PASS" if max_err < 1e-3 else "FAIL"            if status == "PASS":                n_pass += 1            else:                n_fail += 1            print(f"  seed={seed:5d} channel={name:14s}: "                  f"max_err={max_err:.6f}  n_slots_diff={n_slots_diff}/"                  f"{2 * N_DATA_TOTAL}  [{status}]")    print(f"\nResult: {n_pass} PASS, {n_fail} FAIL")    if n_fail == 0:        print("Two independent numpy transliterations agree "              "-> primary host reference is trustworthy for silicon gate (a).")        sys.exit(0)    else:        print("MISMATCH -- fix the primary reference before running silicon.")        sys.exit(1)if __name__ == "__main__":    main()